"""No-branding test: shipped code and docs must look like the author's own
work -- no AI/Muse attribution, watermarks, or generated-by headers."""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

BANNED = [
    "Muse",
    "Anthropic",
    "AI-generated",
    "generated by AI",
    "generated by Muse",
    "written by Muse",
]


def shipped_files():
    skip_dirs = {".git", "__pycache__", ".pytest_cache", ".venv", "venv"}
    skip_suffixes = {".pyc"}
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        if any(part in skip_dirs for part in path.parts):
            continue
        if path.suffix in skip_suffixes:
            continue
        if path.name in {"measured.json", "experiment.json", "drift_probe.json"}:
            continue
        if path == Path(__file__).resolve():
            continue  # this file itself lists the banned phrases
        yield path


def test_no_branding_in_shipped_files():
    offenders = []
    for path in shipped_files():
        try:
            text = path.read_text(errors="ignore")
        except Exception:
            continue
        for phrase in BANNED:
            if phrase in text:
                offenders.append(f"{path.relative_to(ROOT)}: {phrase!r}")
    assert not offenders, "\n".join(offenders)
